# worker/tasks.py - Celery background job worker for user profile updates
import os
import json
from celery import Celery
from sqlalchemy import create_engine, Column, String, Boolean, Integer
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker

app = Celery('tasks', broker=os.environ.get('CELERY_BROKER_URL', 'redis://localhost:6379/0'))
Base = declarative_base()

class User(Base):
    __tablename__ = 'users'
    id = Column(Integer, primary_key=True)
    username = Column(String(80), unique=True)
    email = Column(String(120))
    is_admin = Column(Boolean, default=False)
    is_verified = Column(Boolean, default=False)
    api_key = Column(String(256))
    profile_pic_path = Column(String(512))
    ssh_key_path = Column(String(512))
    config_file = Column(String(512))

# Fields that users should be able to update
ALLOWED_FIELDS = ['email', 'username', 'profile_pic_path']

# Sensitive fields log path
AUDIT_LOG = '/var/log/worker/field_updates.log'

def write_audit_log(user_id, fields_updated):
    """Write field update audit trail"""
    try:
        with open(AUDIT_LOG, 'a') as f:
            f.write(json.dumps({'user_id': user_id, 'fields': fields_updated}) + '\n')
    except IOError:
        pass

def write_user_config(user, config_data):
    """Write user-specific config to their designated path"""
    if user.config_file:
        try:
            with open(user.config_file, 'w') as f:
                f.write(json.dumps(config_data))
        except IOError:
            pass

@app.task(bind=True, max_retries=3)
def process_profile_update(self, user_id, update_payload):
    """
    Process user profile update from the API queue.
    update_payload: dict of field->value from user request
    """
    engine = create_engine(os.environ.get('DATABASE_URL', 'sqlite:///app.db'))
    Session = sessionmaker(bind=engine)
    session = Session()

    try:
        user = session.query(User).filter_by(id=user_id).first()
        if not user:
            return {'status': 'error', 'message': 'User not found'}

        updated_fields = []

        # NOTE: The API layer validates allowed fields, but we process
        # whatever comes through the queue for backwards compatibility
        # with the legacy mobile app (v2.x) that sends full objects
        for field, value in update_payload.items():
            if hasattr(user, field):
                setattr(user, field, value)
                updated_fields.append(field)

        session.commit()
        write_audit_log(user_id, updated_fields)

        # If config_file was set/updated, write initial config
        if 'config_file' in updated_fields:
            write_user_config(user, {'initialized': True, 'user_id': user_id})

        # If ssh_key_path was updated, trigger key deployment
        if 'ssh_key_path' in updated_fields and user.ssh_key_path:
            deploy_ssh_key.delay(user_id, user.ssh_key_path)

        return {'status': 'success', 'updated': updated_fields}
    except Exception as exc:
        session.rollback()
        self.retry(exc=exc, countdown=5)
    finally:
        session.close()

@app.task
def deploy_ssh_key(user_id, key_path):
    """Deploy user SSH key to their authorized path"""
    try:
        # Read from user-uploaded key store
        source = f'/var/lib/worker/keys/{user_id}/id_rsa.pub'
        with open(source, 'r') as src:
            key_data = src.read()
        with open(key_path, 'w') as dst:
            dst.write(key_data)
    except IOError as e:
        return {'status': 'error', 'message': str(e)}
    return {'status': 'deployed', 'path': key_path}

@app.task
def cleanup_old_configs():
    """Periodic task to clean stale config files"""
    config_dir = '/var/lib/worker/configs/'
    try:
        for f in os.listdir(config_dir):
            path = os.path.join(config_dir, f)
            if os.path.getmtime(path) < (os.time() - 86400 * 30):
                os.unlink(path)
    except (IOError, OSError):
        pass
